CREATE COLUMN TABLE "TEST_AP"."OCFW" ("CFWId" INTEGER CS_INT NOT NULL , "CFWName" NVARCHAR(100) NOT NULL , "LineNum" NVARCHAR(5), "Postable" NVARCHAR(1) DEFAULT 'Y', "FatherNum" INTEGER CS_INT, "Levels" SMALLINT CS_INT DEFAULT 3, "GroupMask" SMALLINT CS_INT DEFAULT 1, "GroupLine" INTEGER CS_INT, "ExtrMatch" INTEGER CS_INT, "IntrMatch" INTEGER CS_INT, "RateDifCFW" INTEGER CS_INT, "DataSource" SMALLINT CS_INT, "Attr" SMALLINT CS_INT, "Direction" SMALLINT CS_INT, PRIMARY KEY ("CFWId")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "OCFW_INTER_KEY" ON "TEST_AP"."OCFW" ( "FatherNum" ASC );
CREATE UNIQUE INDEX "OCFW_INDEX_KEY" ON "TEST_AP"."OCFW" ( "CFWName" ASC )